'use strict';

const sharp = require('sharp');
sharp.cache(false);
sharp.concurrency(1);
const axios = require('axios');
const path  = require('path');
const fs    = require('fs');

// ─── Canvas ───────────────────────────────────────────────────────────────────
const W = 1200;
const H = 628;

// ─── Blue / white split geometry ─────────────────────────────────────────────
const SPLIT_X = Math.round(W * 0.40);
const WHITE_SECTION_W = W - SPLIT_X;
const CURVE_CTRL_X = SPLIT_X - 147;

// ─── Brand palette ───────────────────────────────────────────────────────────
const BLUE   = '#1A1AE6';
const ORANGE = '#ff6a03';
const WHITE  = '#FFFFFF';

// ─── Badge geometry ──────────────────────────────────────────────────────────
const BADGE_X  = 40;
const BADGE_Y  = 140;
const BADGE_BW = 270;   // body width; arrow tip adds another 23 px
const BADGE_H  = 64;
const BADGE_R  = 12;    // corner radius (left side only)
const ORANGE_PRICE_GAP = 20;
const ORANGE_TITLE_GAP = 20;

// ─── Left-section vertical rhythm ────────────────────────────────────────────
const PRICE_CX = 262;   // horizontal centre of the left section
const PRICE_Y  = 341;   // only feeds the unused fire-icon layout math below; buildSVG
                        // derives its own centered price position from blockH instead
const REG_FONT = 48;

// ─── Logo box (top-right) ─────────────────────────────────────────────────────
// White rounded rect that backs the logo image (or fallback text).
// Logo image is resized to fit max 220×68 and centred within the box.
const LOGO_W = 180;
const LOGO_H = 90;
const LOGO_X = W - LOGO_W - 10;
const LOGO_Y = 10;
const LOGO_IMG_MAX_W = Math.round(149 * 0.95 * 0.95);
const LOGO_IMG_MAX_H = Math.round(56 * 0.95 * 0.95);
const PRODUCT_SAFE_TOP = LOGO_Y + Math.round(LOGO_H * 0.8);
const PRODUCT_SHIFT_LEFT = Math.round(580 * 0.1);

const BORDER_SAMPLE_SIZE = 64;
const BORDER_DEPTH = 3;
const BORDER_MATCH_RATIO = 0.92;

async function detectTrimmableBackground(imageBuffer) {
  const { data, info } = await sharp(imageBuffer)
    .ensureAlpha()
    .resize(BORDER_SAMPLE_SIZE, BORDER_SAMPLE_SIZE, { fit: 'fill' })
    .raw()
    .toBuffer({ resolveWithObject: true });

  let borderPixels = 0;
  let transparentPixels = 0;
  let whitePixels = 0;

  for (let y = 0; y < info.height; y += 1) {
    for (let x = 0; x < info.width; x += 1) {
      const isBorder = x < BORDER_DEPTH || y < BORDER_DEPTH ||
        x >= info.width - BORDER_DEPTH || y >= info.height - BORDER_DEPTH;
      if (!isBorder) continue;

      const offset = (y * info.width + x) * info.channels;
      const red = data[offset];
      const green = data[offset + 1];
      const blue = data[offset + 2];
      const alpha = data[offset + 3];
      borderPixels += 1;

      if (alpha <= 15) {
        transparentPixels += 1;
      } else if (red >= 245 && green >= 245 && blue >= 245) {
        whitePixels += 1;
      }
    }
  }

  const transparentRatio = transparentPixels / borderPixels;
  const plainBackgroundRatio = (transparentPixels + whitePixels) / borderPixels;

  if (transparentRatio >= BORDER_MATCH_RATIO) return 'transparent';
  if (plainBackgroundRatio >= BORDER_MATCH_RATIO) return 'white';
  return null;
}

async function trimPlainProductBackground(imageBuffer) {
  const backgroundType = await detectTrimmableBackground(imageBuffer);
  if (!backgroundType) return { buffer: imageBuffer, trimmed: false, backgroundType: null };

  const background = backgroundType === 'transparent'
    ? { r: 0, g: 0, b: 0, alpha: 0 }
    : { r: 255, g: 255, b: 255, alpha: 1 };
  const trimmed = await sharp(imageBuffer)
    .ensureAlpha()
    .trim({ background, threshold: 12 })
    .png()
    .toBuffer();
  const metadata = await sharp(trimmed).metadata();

  if (!metadata.width || !metadata.height || metadata.width < 2 || metadata.height < 2) {
    return { buffer: imageBuffer, trimmed: false, backgroundType: null };
  }
  return { buffer: trimmed, trimmed: true, backgroundType };
}

// ─── Embedded assets (base64) ─────────────────────────────────────────────────
const LOGO_B64 = '';
const FIRE_B64 = '';
const INTER_REG_B64  = '';
const INTER_BOLD_B64 = '';

function loadAssetBuffer(filename) {
  if (filename === 'logo.jpg' || filename === 'logo.png') {
    return Buffer.from(LOGO_B64, 'base64');
  }
  if (filename === 'fire.jpg') {
    return Buffer.from(FIRE_B64, 'base64');
  }
  console.error('[generator] unknown asset:', filename);
  return null;
}

const LOGO_URL = 'https://cdn.shopify.com/s/files/1/0987/7903/7992/files/logo.png?v=1782185728';
let cachedLogoDataPromise = null;
let cachedFireDataPromise = null;

function getLogoData() {
  if (!cachedLogoDataPromise) {
    cachedLogoDataPromise = (async () => {
      const axios = require('axios');
      const res = await axios.get(LOGO_URL, { responseType: 'arraybuffer', timeout: 10_000 });
      const resized = await sharp(Buffer.from(res.data))
        .resize(LOGO_IMG_MAX_W, LOGO_IMG_MAX_H, { fit: 'inside' })
        .png()
        .toBuffer();
      const { width: lw, height: lh } = await sharp(resized).metadata();
      return { buffer: resized, w: lw, h: lh };
    })().catch(async err => {
      console.warn('[generator] logo fetch failed:', err.message);
      cachedLogoDataPromise = null;
      const embeddedLogo = loadAssetBuffer('logo.png');
      const resized = await sharp(embeddedLogo)
        .resize(LOGO_IMG_MAX_W, LOGO_IMG_MAX_H, { fit: 'inside' })
        .png()
        .toBuffer();
      const { width: lw, height: lh } = await sharp(resized).metadata();
      return { buffer: resized, w: lw, h: lh };
    });
  }
  return cachedLogoDataPromise;
}

const FIRE_URL = 'https://cdn.shopify.com/s/files/1/0987/7903/7992/files/fire.jpg?v=1782179945';

function getFireData() {
  if (!cachedFireDataPromise) {
    cachedFireDataPromise = (async () => {
      const axios = require('axios');
      const res = await axios.get(FIRE_URL, { responseType: 'arraybuffer', timeout: 10_000 });
      const resized = await sharp(Buffer.from(res.data))
        .resize({ height: 50, fit: 'inside' })
        .png()
        .toBuffer();
      const { width: fw, height: fh } = await sharp(resized).metadata();
      return { buffer: resized, w: fw, h: fh };
    })().catch(err => {
      console.warn('[generator] fire fetch failed:', err.message);
      cachedFireDataPromise = null;
      return null;
    });
  }
  return cachedFireDataPromise;
}

// ─── Public API ───────────────────────────────────────────────────────────────

async function generateProductImage(product) {
  console.log('[generator] entered generateProductImage');

  console.log('[generator] step 1: parsing product data');
  const {
    id,
    price,
    compare_at_price,
    image_url,
    image_buffer     = null,
    badge_text       = null,
    deal_badge_text  = null,
    deal_sale_price  = null,
    deal_reg_price   = null,
    deal_title       = null,
  } = product;

  const composites = [];

  // 1. Product image — composited into the white right area (x:620, 580×628)
  let productImgBuffer = image_buffer || null;
  if (!productImgBuffer && image_url) {
    try {
      productImgBuffer = await downloadImage(image_url);
    } catch (err) {
      console.warn('[generator] product image fetch failed (non-fatal):', err.message);
    }
  }
  if (productImgBuffer) {
    const preparedImage = await trimPlainProductBackground(productImgBuffer);
    if (preparedImage.trimmed) {
      console.log(`[generator] trimmed ${preparedImage.backgroundType} product-image padding`);
    } else {
      console.log('[generator] preserving product image background');
    }
    const MAX_W = Math.round(588 * 1.05);
    const MAX_H = Math.round(553 * 1.05);
    const fitted = await sharp(preparedImage.buffer)
      .resize(MAX_W, MAX_H, { fit: 'inside', withoutEnlargement: false })
      .png()
      .toBuffer();
    const { width: fw, height: fh } = await sharp(fitted).metadata();
    const left = SPLIT_X + Math.round((WHITE_SECTION_W - fw) / 2) - 40;
    const top  = Math.round((H - fh) / 2);
    composites.push({ input: fitted, top, left });
  }

  // 2. Try to load the logo file
  console.log('[generator] step 2: fetching logo');
  const logoData = await getLogoData();

  // 3. Fire icon removed
  const fireData = null;

  // 4. SVG overlay: blue section + badge + prices + logo box (+ optional text fallback)
  // Mirror buildSVG mode detection for fire composite positioning
  const _titleMode     = !!(deal_title && deal_title.trim());
  const _badgeHidden   = deal_badge_text === 'hide';
  const _titleOnlyMode = _titleMode && _badgeHidden;
  const _saleStrLayout = deal_sale_price === 'hide' ? '' : (deal_sale_price || formatCurrency(price));
  const _badgeOnly     = !_titleMode && !_saleStrLayout;
  const _priceFSLayout = getPriceFontSize(_saleStrLayout);
  let computedBadgeY;
  if (_titleOnlyMode) {
    computedBadgeY = 0;  // no fire in title-only mode
  } else if (_titleMode) {
    const _tLines  = wrapText(truncateText(deal_title.trim(), 60), TITLE_MAX_W, TITLE_FS);
    const _tBlockH = _tLines.length * TITLE_FS + (_tLines.length - 1) * TITLE_LINE_GAP;
    computedBadgeY = Math.floor((H - (BADGE_H + ORANGE_TITLE_GAP + _tBlockH)) / 2);
  } else if (_badgeOnly) {
    computedBadgeY = Math.floor((H - BADGE_H) / 2);
  } else {
    computedBadgeY = PRICE_Y - Math.floor(_priceFSLayout / 2) - ORANGE_PRICE_GAP - BADGE_H;
  }
  console.log('[generator] step 4: building SVG');
  const svgBuf = Buffer.from(buildSVG({ price, compare_at_price, badge_text: _badgeHidden ? null : (deal_badge_text || badge_text), deal_title, badgeHidden: _badgeHidden, deal_sale_price, deal_reg_price, showLogoText: logoData === null, showFireImg: fireData !== null && !_badgeHidden, fireWidth: fireData?.w ?? 0 }));

  // 5. Building composites array
  console.log('[generator] step 5: building composites array');
  composites.push({ input: svgBuf, top: 0, left: 0 });

  if (fireData && !_badgeOnly && !_badgeHidden) {
    composites.push({
      input: fireData.buffer,
      left: BADGE_X + 12,
      top:  computedBadgeY + Math.floor((BADGE_H - fireData.h) / 2),
    });
  }

  if (logoData) {
    composites.push({
      input: logoData.buffer,
      top: LOGO_Y,
      left: W - 10 - logoData.w,
    });
  }

  // 6. Flatten to JPEG buffer
  const buffer = await sharp({ create: { width: W, height: H, channels: 3, background: WHITE } })
    .composite(composites)
    .jpeg({ quality: 90, chromaSubsampling: '4:4:4', mozjpeg: false })
    .toBuffer();
  console.log('[generator] step 7: sharp complete');

  console.log('[generator] step 8: done, returning buffer');
  return buffer;
}

module.exports = {
  generateProductImage,
  detectTrimmableBackground,
  trimPlainProductBackground,
};

// ─── Image download ───────────────────────────────────────────────────────────

async function downloadImage(url) {
  const res = await axios.get(url, {
    responseType: 'arraybuffer',
    timeout: 8_000,
    headers: { 'User-Agent': 'ShopifyImageApp/1.0' },
  });
  return Buffer.from(res.data);
}

// ─── SVG overlay ─────────────────────────────────────────────────────────────

// ─── Font rendering via opentype.js (no system fonts / fontconfig needed) ────
// Uses low-level glyph API to bypass BIDI/CCMP pipeline (unsupported in Inter WOFF).
const opentype = require('opentype.js');

let _fontReg  = null;
let _fontBold = null;

function fontReg() {
  if (!_fontReg) {
    const buf = Buffer.from(INTER_REG_B64, 'base64');
    _fontReg = opentype.parse(buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength));
  }
  return _fontReg;
}

function fontBold() {
  if (!_fontBold) {
    const buf = Buffer.from(INTER_BOLD_B64, 'base64');
    _fontBold = opentype.parse(buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength));
  }
  return _fontBold;
}

function midToBaseline(y, fontSize, bold) {
  const f = bold ? fontBold() : fontReg();
  return y + (f.ascender + f.descender) / 2 / f.unitsPerEm * fontSize;
}

// Glyph advance width without going through string-shaping pipeline
function glyphAdv(glyph, fontSize, font) {
  return (glyph.advanceWidth || 0) / font.unitsPerEm * fontSize;
}

// Total advance width of a string using per-char glyph lookup
function textWidth(text, fontSize, font, letterSpacing) {
  let w = 0;
  for (const ch of text) w += glyphAdv(font.charToGlyph(ch), fontSize, font) + letterSpacing;
  return w - letterSpacing;
}

// Render string as a single SVG path d= value, bypassing BIDI/CCMP entirely
function glyphsToPathData(text, startX, baseY, fontSize, font, letterSpacing) {
  let cx = startX;
  let d  = '';
  for (const ch of text) {
    const g = font.charToGlyph(ch);
    const pd = g.getPath(cx, baseY, fontSize).toPathData(1);
    if (pd) d += pd + ' ';
    cx += glyphAdv(g, fontSize, font) + letterSpacing;
  }
  return d.trim();
}

// Returns SVG <path> element(s) for the given text string.
// opts: { bold, fill, center, middleBaseline, letterSpacing, shadow:{dx,dy,fill}, strokeColor, strokeWidth }
function svgPath(text, x, y, fontSize, opts = {}) {
  const { bold = false, fill = '#000', center = false,
          middleBaseline = false, letterSpacing = 0, shadow,
          strokeColor = null, strokeWidth = 0 } = opts;
  const f     = bold ? fontBold() : fontReg();
  const baseY = middleBaseline ? midToBaseline(y, fontSize, bold) : y;
  const drawX = center ? x - textWidth(text, fontSize, f, letterSpacing) / 2 : x;

  let out = '';
  if (shadow) {
    const sd = glyphsToPathData(text, drawX + (shadow.dx || 0), baseY + (shadow.dy || 0), fontSize, f, letterSpacing);
    if (sd) out += `<path fill="${shadow.fill}" d="${sd}"/>`;
  }
  const pd = glyphsToPathData(text, drawX, baseY, fontSize, f, letterSpacing);
  if (pd) {
    const strokeAttrs = strokeColor ? ` stroke="${strokeColor}" stroke-width="${strokeWidth}" stroke-linejoin="round"` : '';
    out += `<path fill="${fill}"${strokeAttrs} d="${pd}"/>`;
  }
  return out;
}
const TITLE_FS       = 44;
const TITLE_LINE_GAP = 12;   // vertical gap between title lines (badge+title mode)
const TITLE_MAX_W    = 350;

const TITLE_ONLY_MAX_W = 350;

// Truncate text to charLimit characters at word boundary.
function truncateText(text, charLimit = 60) {
  if (text.length <= charLimit) return text;
  const sliced    = text.slice(0, charLimit);
  const lastSpace = sliced.lastIndexOf(' ');
  return (lastSpace > 0 ? sliced.slice(0, lastSpace) : sliced).trimEnd();
}

// Balanced word-wrap: binary-searches for the narrowest column that still fits
// all words in maxLines, producing evenly-sized lines instead of a greedy layout.
function wrapText(text, maxWidth, fontSize, maxLines = 3) {
  const font  = fontBold();
  const words = text.trim().split(/\s+/);

  // Inner greedy pass using a given column width. Returns null if it can't fit.
  function tryWrap(colW) {
    const lines = [];
    let cur = '';
    for (const word of words) {
      const test = cur ? `${cur} ${word}` : word;
      if (textWidth(test, fontSize, font, 0) <= colW) {
        cur = test;
      } else {
        if (cur) lines.push(cur);
        if (lines.length === maxLines) return null;
        cur = word;
      }
    }
    if (cur && lines.length < maxLines) lines.push(cur);
    return lines;
  }

  // Binary-search for the minimum column width that fits in maxLines.
  // This naturally balances line lengths.
  let lo = maxWidth / maxLines;
  let hi = maxWidth;
  for (let i = 0; i < 24; i++) {
    const mid = (lo + hi) / 2;
    if (tryWrap(mid) !== null) hi = mid; else lo = mid;
  }

  const balanced = tryWrap(Math.ceil(hi)) || tryWrap(maxWidth);
  if (balanced) return balanced;

  // Text needs more lines than maxLines at maxWidth — fall back to unlimited greedy wrap
  // so all words still render (block-height centering adapts automatically)
  const lines = [];
  let cur = '';
  for (const word of words) {
    const test = cur ? `${cur} ${word}` : word;
    if (textWidth(test, fontSize, font, 0) <= maxWidth) {
      cur = test;
    } else {
      if (cur) lines.push(cur);
      cur = word;
    }
  }
  if (cur) lines.push(cur);
  return lines;
}

function formatCurrency(value, roundUp = false) {
  if (value === null || value === undefined || value === '') return '';
  const amount = Number(String(value).replace(/[^\d.-]/g, ''));
  if (!Number.isFinite(amount)) return String(value);
  const formattedAmount = roundUp
    ? Math.ceil(amount).toLocaleString('en-US')
    : amount.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return `$${formattedAmount}`;
}

function getPriceFontSize(priceText) {
  // Conservative flat bound for the larger tiers (their text sits far enough from
  // the canvas's vertical centre that the straight-line approximation is the safe one).
  const maxWidth = CURVE_CTRL_X - BADGE_X - 12;
  // Below ~66px, long prices push toward the smaller tiers, which sit close to the
  // vertical centre where the actual bezier curve bulges further right than the flat
  // approximation assumes. That gives real extra room there — computed from the curve's
  // true minimum x (~370 at y=314) rather than guessed — so use the wider, accurate
  // budget for just those tiers instead of inheriting the larger tiers' conservative one.
  const curveMaxWidth = 317;
  const LADDER = [112, 100, 89, 82, 76, 72, 66, 60, 54, 50];
  for (const fontSize of LADDER) {
    const budget = fontSize <= 66 ? curveMaxWidth : maxWidth;
    if (textWidth(priceText, fontSize, fontBold(), 0) <= budget) return fontSize;
  }
  // Safety net: glyph advance widths scale exactly linearly with font size,
  // so this computes the precise size where the string fits curveMaxWidth instead
  // of guessing a fixed fallback that could still overflow for long strings.
  const smallest = LADDER[LADDER.length - 1];
  const widthAtSmallest = textWidth(priceText, smallest, fontBold(), 0);
  return Math.max(24, Math.floor(smallest * curveMaxWidth / widthAtSmallest));
}

function buildSVG({ price, compare_at_price, badge_text, deal_title, badgeHidden, deal_sale_price, deal_reg_price, showLogoText, showFireImg, fireWidth }) {

  // ── Mode detection ────────────────────────────────────────────────────────
  const titleMode     = !!(deal_title && deal_title.trim());
  // titleOnlyMode: no badge — large left-aligned title fills the left area
  const titleOnlyMode = titleMode && !!badgeHidden;
  // badgeWithTitle: badge shows + smaller centered title below
  const badgeWithTitle = titleMode && !badgeHidden;

  // Apply 60-char cap before wrapping
  const dealTitleCapped = deal_title ? truncateText(deal_title.trim(), 60) : '';

  // Title-only: auto-size font so up to 60 chars fits within the blue area
  // Short text → big font; longer text → smaller font, more lines allowed
  const titleOnlyFS = dealTitleCapped.length <= 20 ? 80
                    : dealTitleCapped.length <= 40 ? 64
                    :                                50;
  const titleOnlyLH = Math.round(titleOnlyFS * 1.3);
  const titleOnlyMaxLines = dealTitleCapped.length <= 20 ? 3
                           : dealTitleCapped.length <= 40 ? 5
                           :                                6;
  // Short text uses wider column (340px) so "Free $10" fits on one line at 80px
  const titleOnlyMaxW = TITLE_ONLY_MAX_W;

  const titleOnlyLines = titleOnlyMode
    ? (wrapText(dealTitleCapped, titleOnlyMaxW, titleOnlyFS, titleOnlyMaxLines) || []) : [];
  const titleOnlyBlockH = titleOnlyLines.length > 0
    ? (titleOnlyLines.length - 1) * titleOnlyLH + titleOnlyFS : 0;
  const titleOnlyStartY = Math.floor((H - titleOnlyBlockH) / 2);

  // Badge+title wrapping (38px, centered below badge)
  const titleLines = badgeWithTitle
    ? (wrapText(dealTitleCapped, TITLE_MAX_W, TITLE_FS) || []) : [];

  // ── Price maths ────────────────────────────────────────────────────────────
  const saleNum    = parseFloat(price) || 0;
  const compareRaw = parseFloat(compare_at_price) || 0;

  // "hide" suppresses all price rows; empty price triggers badge-only
  const saleStr   = deal_sale_price === 'hide' ? '' : (deal_sale_price ? formatCurrency(deal_sale_price) : formatCurrency(price));
  const badgeOnly = !titleMode && !saleStr;

  const showReg     = !titleMode && !badgeOnly && (!!(deal_reg_price) || (compareRaw > 0 && compareRaw > saleNum));
  const regPriceStr = deal_reg_price ? formatCurrency(deal_reg_price) : (showReg && compareRaw > 0 ? formatCurrency(compareRaw, true) : '');

  const effectiveSaleAmt = parseFloat((deal_sale_price && deal_sale_price !== 'hide' ? deal_sale_price : price)?.replace(/[^\d.]/g, '')) || saleNum;
  const effectiveRegAmt  = parseFloat(deal_reg_price?.replace(/[^\d.]/g, '')) || compareRaw;

  const savingsPct = effectiveSaleAmt > 0 && effectiveRegAmt > effectiveSaleAmt
    ? Math.round(((effectiveRegAmt - effectiveSaleAmt) / effectiveRegAmt) * 100)
    : null;

  const badgeLabel = badge_text
    ? badge_text
    : (savingsPct ? `${savingsPct}% OFF` : 'DEAL');

  // ── Badge text centre x ────────────────────────────────────────────────────
  // Fire icon hidden in badge-only and title-only modes
  const badgeTX = (!badgeOnly && !titleOnlyMode && showFireImg)
    ? BADGE_X + 8 + fireWidth + Math.floor((BADGE_BW - 8 - fireWidth) / 2)
    : BADGE_X + BADGE_BW / 2 + 6;

  // ── Sale price font size ───────────────────────────────────────────────────
  const priceFS = getPriceFontSize(saleStr);

  // ── Reg. price geometry ────────────────────────────────────────────────────
  const regLabelW  = textWidth('Reg. ', REG_FONT, fontReg(), 0);
  const regPriceW  = showReg ? textWidth(regPriceStr, REG_FONT, fontReg(), 0) : 0;
  const regPriceX0 = BADGE_X + regLabelW;

  // ── Vertical layout ────────────────────────────────────────────────────────
  const titleBlockH = titleLines.length > 0
    ? titleLines.length * TITLE_FS + (titleLines.length - 1) * TITLE_LINE_GAP : 0;
  const blockH = badgeWithTitle
    ? BADGE_H + ORANGE_TITLE_GAP + titleBlockH
    : badgeOnly
      ? BADGE_H
      : BADGE_H + ORANGE_PRICE_GAP + priceFS + (showReg ? 25 + REG_FONT : 0);
  // titleOnlyMode centers text itself; all other badge-bearing modes center the
  // whole block (badge + price + reg price) vertically via blockH
  const dynamicBadgeY = titleOnlyMode
    ? 0
    : Math.floor((H - blockH) / 2);
  const priceY  = dynamicBadgeY + BADGE_H + ORANGE_PRICE_GAP + Math.floor(priceFS / 2);
  const regY    = priceY + Math.floor(priceFS / 2) + 25;
  const strikeY = regY;

  // ── Blue left-section bezier path ─────────────────────────────────────────
  const bluePath =
    `M 0 0 L ${SPLIT_X} 0 ` +
    `C ${CURVE_CTRL_X} ${H * 0.25}, ${CURVE_CTRL_X} ${H * 0.75}, ${SPLIT_X} ${H} ` +
    `L 0 ${H} Z`;

  // ── Orange badge: rounded-left rect + right arrow ─────────────────────────
  const arrowX  = BADGE_X + BADGE_BW + 23;
  const midY    = dynamicBadgeY + BADGE_H / 2;
  const bBot    = dynamicBadgeY + BADGE_H;

  const badgePath =
    `M ${BADGE_X + BADGE_R},${dynamicBadgeY} ` +
    `H ${BADGE_X + BADGE_BW} ` +
    `L ${arrowX},${midY} ` +
    `L ${BADGE_X + BADGE_BW},${bBot} ` +
    `H ${BADGE_X + BADGE_R} ` +
    `Q ${BADGE_X},${bBot} ${BADGE_X},${bBot - BADGE_R} ` +
    `V ${dynamicBadgeY + BADGE_R} ` +
    `Q ${BADGE_X},${dynamicBadgeY} ${BADGE_X + BADGE_R},${dynamicBadgeY} Z`;

  return `<svg width="${W}" height="${H}" xmlns="http://www.w3.org/2000/svg" xml:space="preserve">

  <!-- ══ Blue left section ══ -->
  <path d="${bluePath}" fill="${BLUE}"/>

  <!-- ══ Orange badge (hidden in title-only mode) ══ -->
  ${!badgeHidden ? `
  <path d="${badgePath}" fill="${ORANGE}"/>
  ${(()=>{ const fs = badgeOnly ? 63 : (badgeLabel.length <= 8 ? 55 : badgeLabel.length <= 11 ? 49 : 44); return svgPath(badgeLabel, badgeTX, midY + 2, fs, { bold: true, fill: WHITE, center: true, middleBaseline: true, strokeColor: WHITE, strokeWidth: 1.5 }); })()}
  ` : ''}

  <!-- ══ Title-only: large left-aligned text, no badge ══ -->
  ${titleOnlyMode ? titleOnlyLines.map((line, i) => {
    const cy = titleOnlyStartY + i * titleOnlyLH + Math.floor(titleOnlyFS / 2);
    return svgPath(line, BADGE_X, cy, titleOnlyFS, { bold: true, fill: WHITE, middleBaseline: true, strokeColor: WHITE, strokeWidth: 2.5 });
  }).join('') : ''}

  <!-- ══ Badge+title: left-aligned title below badge ══ -->
  ${badgeWithTitle ? titleLines.map((line, i) => {
    const cy = dynamicBadgeY + BADGE_H + ORANGE_TITLE_GAP + i * (TITLE_FS + TITLE_LINE_GAP) + TITLE_FS / 2;
    return svgPath(line, BADGE_X, cy, TITLE_FS, { bold: true, fill: WHITE, middleBaseline: true, strokeColor: WHITE, strokeWidth: 1.5 });
  }).join('') : ''}

  <!-- ══ Sale price ══ -->
  ${!titleMode && saleStr ? svgPath(saleStr, BADGE_X, priceY, priceFS, { bold: true, fill: WHITE, middleBaseline: true, strokeColor: WHITE, strokeWidth: 1.5 }) : ''}

  <!-- ══ Reg. price ══ -->
  ${showReg ? `
  ${svgPath('Reg. ', BADGE_X, regY, REG_FONT, { fill: WHITE, middleBaseline: true })}
  ${svgPath(regPriceStr, regPriceX0, regY, REG_FONT, { fill: WHITE, middleBaseline: true })}
  <line x1="${regPriceX0 - 2}" y1="${strikeY}"
        x2="${regPriceX0 + regPriceW + 2}" y2="${strikeY}"
        stroke="${ORANGE}" stroke-width="3.5"/>
  ` : ''}

  ${showLogoText ? `
  ${svgPath('SIMPLEX', LOGO_X + 18, LOGO_Y + 26, 23, { bold: true, fill: BLUE, middleBaseline: true })}
  ${svgPath('DEALS',   LOGO_X + 18, LOGO_Y + 54, 23, { bold: true, fill: ORANGE, middleBaseline: true, letterSpacing: 5 })}
  ` : ''}

</svg>`;
}
